<?php declare(strict_types=1);
use Kulturhus\Verein\{BalanceLedger,BalanceSources,BalancePeriodLedger,BalancePeriodSources,SettingsSchema,Finance,Documents};

// Actual journals in four separate owned clubs. Invoice recognition stays intact;
// the existing returned money reopens the original receivable/payable account.
putenv('VEREIN_BALANCE_WORKSPACE=1');putenv('VEREIN_BALANCE_PERIODS=1');putenv('VEREIN_MODE=synthetic');
foreach(['annual','period']as$mode)foreach(['expense','income']as$kind){
    $club='own-partial-balance-'.$mode.'-'.$kind;$actor=$club.'-admin';$db->prepare('INSERT INTO clubs VALUES(?,?)')->execute([$club,'Own actual partial return balance']);$db->prepare("INSERT INTO actors(id,club_id,role,is_superuser)VALUES(?,?,'member',1)")->execute([$actor,$club]);
    $tax=array_replace(SettingsSchema::defaults('tax'),['accounting_basis'=>'balance','input_tax_eligibility'=>'no','fiscal_start'=>'2026-01-01']);$db->prepare("INSERT INTO club_settings(club_id,section,payload,version,updated_at)VALUES(?,'tax',?,1,?)")->execute([$club,json_encode($tax,JSON_THROW_ON_ERROR),gmdate('c')]);$finance=new Finance($db,$actor);$account=$finance->createAccount('Own original cashless account','offline','1000','2026-01-01');$sources=$mode==='annual'?new BalanceSources($db,$actor):new BalancePeriodSources($db,$actor);$ledger=$mode==='annual'?new BalanceLedger($db,$actor):new BalancePeriodLedger($db,$actor);$period=['start'=>'2026-01-01','end'=>'2026-12-31'];$bank=array_key_first((new BalanceSources($db,$actor))->bankAccounts());
    if($mode==='annual'){$ledger->create(2026);$ledger->setup(2026,1,$ledger->report(2026)['accounts'],[['account'=>$bank,'debit_cents'=>100000,'credit_cents'=>0,'sphere'=>''],['account'=>'equity','debit_cents'=>0,'credit_cents'=>100000,'sphere'=>'']],'equity','Own actual reviewed opening statement',true);$target=2026;}
    else{$target=$ledger->create($period,'Own reviewed actual annual period',true);$ledger->setup($target,1,[['account'=>$bank,'debit_cents'=>100000,'credit_cents'=>0,'sphere'=>''],['account'=>'equity','debit_cents'=>0,'credit_cents'=>100000,'sphere'=>'']],'Own actual reviewed opening statement',true);}
    $import=static function(string$type,string$id,array$options=[])use($mode,$period,$sources,$ledger,$target):array{$p=$sources->preview($mode==='annual'?2026:$period,$type,$id,$options);if($p['issues'])throw new RuntimeException('Actual '.$mode.' '.$type.': '.implode(' ',$p['issues']));$report=$ledger->report($target);$ledger->importSource($target,(int)$report['version'],$type,$id,$options,$p['hash'],true);return $p;};
    $entry=$finance->createEntry(['kind'=>$kind,'category'=>'general','amount'=>'100','description'=>'Own valid original '.$kind.' demand','document_date'=>'2026-01-02','due_date'=>'2026-01-03','positions'=>[['description'=>'Own whole original item','amount'=>'100','tax_rate'=>'0','sphere'=>'1','account'=>$kind==='expense'?'68150':'42000','booking_key'=>'','input_tax'=>$kind==='expense'?'none':'unknown']]],$key());(new Documents($db,$actor))->upload('own-balance-original.png',base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII='),['title'=>'Own unchanged original','kind'=>'invoice','scope'=>'finance','links'=>['entry:'.$entry]],$key());$options=['recognised_on'=>'2026-01-02','private_paid_on'=>''];$invoice=$import('invoice',$entry,$options);$settlement=$invoice['snapshot']['settlement_account'];
    $source=$finance->createTransaction(['account'=>$account,'direction'=>$kind==='expense'?'expense':'income','amount'=>'100','booked_on'=>'2026-01-23','description'=>'Own whole actual settlement'],$key());$finance->allocate($source,(int)$finance->transactionDetail($source)['version'],$entry,(int)$finance->entry($entry)['version'],'100',$key());$originalPayment=$import('transaction',$source);$before=$ledger->report($target);$assert($before['calculation']['accounts'][$settlement]['amount_cents']===0,'actual '.$mode.' '.$kind.' original payment fully clears its recognized settlement');$oldEntries=$before['entries'];
    $counter=$finance->createTransaction(['account'=>$account,'direction'=>$kind==='expense'?'income':'expense','amount'=>'40','booked_on'=>'2026-01-24','description'=>'Own actual forty returned; demand remains valid'],$key());$amounts=[['allocation_id'=>$finance->allocations($entry)[0]['id'],'amount'=>'40']];$reason='Own actual original demand remains due for the returned forty';$review=$finance->partialReturnReview($counter,$amounts,$reason);$first=$finance->returnPaymentParts($counter,(int)$review['review']['counter']['version'],$amounts,$reason,$key(),$review['hash'],true);$posted=$import('transaction',$counter);$after=$ledger->report($target);
    $assert($after['calculation']['annual_result_cents']===($kind==='expense'?-10000:10000)&&$after['calculation']['accounts'][$settlement]['amount_cents']===4000,'actual '.$mode.' '.$kind.' partial return reopens forty of the original debt without another expense or revenue');
    $freshInvoice=$sources->preview($mode==='annual'?2026:$period,'invoice',$entry,$options);$freshPayment=$sources->preview($mode==='annual'?2026:$period,'transaction',$source);$assert(!$freshInvoice['issues']&&!$freshPayment['issues']&&$freshInvoice['hash']===$invoice['hash']&&$freshPayment['hash']===$originalPayment['hash'],'actual '.$mode.' '.$kind.' partial return preserves both complete original recognition and payment previews');$assert(array_intersect_key($after['entries'],$oldEntries)===$oldEntries&&count($posted['snapshot']['partial_returns'])===1&&$posted['snapshot']['partial_returns'][0]['id']===$first['id'],'actual '.$mode.' '.$kind.' balance retains every old journal entry and explicitly references the new returned-money first');
    $replacement=$finance->createTransaction(['account'=>$account,'direction'=>$kind==='expense'?'expense':'income','amount'=>'40','booked_on'=>'2026-01-25','description'=>'Own actual later settlement of returned forty'],$key());$finance->allocate($replacement,(int)$finance->transactionDetail($replacement)['version'],$entry,(int)$finance->entry($entry)['version'],'40',$key());$import('transaction',$replacement);$final=$ledger->report($target);$assert($final['calculation']['accounts'][$settlement]['amount_cents']===0&&$final['calculation']['annual_result_cents']===($kind==='expense'?-10000:10000),'actual '.$mode.' '.$kind.' later real forty payment clears only the reopened original debt');
}
